#!/usr/bin/env python3
"""Editable curriculum source. Re-run to regenerate curriculum.json. No external dependencies."""
import json
from pathlib import Path

modules=[]
current=None

def module(title,description):
    global current
    current={'id':f'm{len(modules)+1:02}', 'title':title,'description':description,'lessons':[]}
    modules.append(current)

def check(description,script): return {'description':description,'script':script}

# Use distinct distribution families for most exercises, while allowing a task-specific override.
DEFAULT_DISTRO = {'m01':'ubuntu', 'm02':'debian', 'm03':'alma',
                  'm04':'debian', 'm05':'ubuntu', 'm06':'alma',
                  'm07':'debian', 'm08':'ubuntu', 'm09':'alma',
                  'm10':'debian', 'm11':'ubuntu'}

def task(title,description,*checks,setup='',distro=None,hint=''):
    distro = distro or DEFAULT_DISTRO[current['id']]
    lesson=current['lessons'][-1]
    item={'id':f"{lesson['id']}-p{len(lesson['tasks'])+1}", 'title':title,
          'description':description,'distro':distro,'hint':hint,
          'setup':setup,'checks':list(checks)}
    lesson['tasks'].append(item)

def q(question,a,b,c,d,answer,explanation):
    lesson=current['lessons'][-1]
    quiz=lesson['quiz']
    quiz.append({'id':f"{lesson['id']}-q{len(quiz)+1}", 'question':question,
         'options':[a,b,c,d],'answer':str(answer), 'explanation':explanation})

def lesson(title,why,theory,example,diagnostics='',level='Начальный',vm=False):
    n=len(current['lessons'])+1
    lid=f"{current['id']}-l{n:02}"
    md=(f'## Зачем это нужно\n\n{why}\n\n## Разбор механики\n\n{theory}\n\n'
        f'## Практический пример\n\n```bash\n{example.strip()}\n```\n\n'
        f'## Проверка и типичные ошибки\n\n{diagnostics or "Читайте сообщения об ошибках; проверяйте код возврата командой `echo $?`, а результат — повторной командой чтения. Не используйте `sudo` без понимания необходимого уровня доступа."}')
    if vm:
        md+='\n\n> **Полная ВМ:** команды, которым нужны systemd как PID 1, реальная сеть, ядро, загрузчик или блочные устройства, необходимо отрабатывать в отдельной полноценной виртуальной машине. Встроенная лаборатория — контейнер, и эти механизмы в ней намеренно ограничены.'
    current['lessons'].append({'id':lid,'title':title,'level':level,'content':md,'vm':vm,'tasks':[],'quiz':[]})

module('Старт и устройство Linux','От ядра до первого входа в терминал; основные различия семейств ОС.')
lesson('Что такое Linux и из чего состоит ОС',
'Разделяйте ядро, дистрибутив, пакеты и оболочку: это помогает не путать ошибки bash, systemd и Linux.',
'**Ядро** управляет процессами, памятью, драйверами и файловыми системами. **User space** содержит службы и программы, взаимодействующие с ядром через системные вызовы. **Дистрибутив** собирает ядро, репозитории, установщик, пакетный менеджер и настройки. **Shell** интерпретирует команды; терминал лишь отображает ввод/вывод. Ubuntu и Debian используют `apt` и `.deb`, AlmaLinux — `dnf` и `.rpm`. Контейнер разделяет ядро с хостом, полноценная ВМ использует собственное виртуальное ядро. Это принципиально для занятий по загрузке и systemd.',
'uname -r\ncat /etc/os-release\necho "$SHELL"\nps -p 1 -o comm=',
'Команда `uname -r` показывает ядро хоста даже внутри контейнера. Данные в `/etc/os-release` относятся к образу ОС. Не считайте имя процесса 1 в контейнере именем init на реальном сервере.')
task('Паспорт системы','Создайте `/workspace/passport.txt` с двумя строками: первая начинается с `DISTRIBUTION=`, вторая — с `KERNEL=`. Получите значения командами `source /etc/os-release`, `uname -r`; не копируйте значения из примеров.',check('Указаны обе характеристики',"grep -q '^DISTRIBUTION=.' /workspace/passport.txt && grep -q '^KERNEL=.' /workspace/passport.txt"),check('Ядро действительно совпадает',"grep -Fxq \"KERNEL=$(uname -r)\" /workspace/passport.txt"),hint='printf, ID из /etc/os-release и подстановка $(...)')
q('Что делает ядро Linux?','Рисует окна','Распределяет процессы и память','Хранит пароли Git','Заменяет пакетный менеджер',1,'Ядро предоставляет системные вызовы, планировщик, управление памятью и драйверы.')
q('Что верно о контейнере?','Всегда загружает собственное ядро','Имеет физическую сетевую карту','Разделяет ядро хоста','Имеет собственный BIOS',2,'Контейнер изолирует процессы и файловую систему, но использует ядро хоста.')

lesson('Терминал, bash, справка и код возврата','Администрирование начинается с умения получить помощь и разобраться, завершилась ли команда успешно.',
'Командная строка состоит из имени программы, параметров и аргументов. `-l` и `--long` — распространённые формы опций, но у каждой программы свои правила. `man` содержит руководства, `--help` — краткую справку, `type` показывает алиасы и встроенные команды. Bash поддерживает кавычки: одинарные отключают большинство подстановок, двойные сохраняют `$VAR`. Код возврата `0` обычно означает успех, ненулевой — ошибку. `&&` запускает следующую команду только при успехе, `||` при неуспехе.',
'pwd\ntype cd\nls --help | head\nprintf "%s\\n" "$HOME"\nfalse; echo "$?"\ntrue && echo success',
'Не ориентируйтесь исключительно на наличие вывода. Некоторые успешные команды молчат; всегда проверяйте код возврата и состояние объекта.')
task('Первый командный сценарий','Создайте исполняемый `/workspace/hello.sh`, печатающий строго `LinuxAcademy OK` с помощью bash.',check('Файл существует и исполняем',"test -x /workspace/hello.sh"),check('Вывод скрипта верный',"test \"$(/workspace/hello.sh)\" = 'LinuxAcademy OK'"),hint='Начните с #!/bin/bash, используйте printf и chmod +x.')
q('Что означает код возврата 0?','Команда завершилась успешно','Не хватило памяти','Команда всё ещё работает','Нет прав на файл',0,'В Unix обычно нулевой код сигнализирует об успешном завершении.')
q('Что делает `&&` между двумя командами?','Всегда запускает обе параллельно','Запускает вторую лишь при успехе первой','Подменяет стандартный вывод','Записывает ошибки в файл',1,'Bash оценивает статус первой команды и выполняет правую только при нулевом коде.')

lesson('Иерархия каталогов FHS','Знание структуры системы помогает отличить настройки, данные приложений и временные файлы.',
'`/etc` хранит конфигурацию, `/var` — изменяемые данные и логи, `/home` — каталоги пользователей, `/usr` — большинство пользовательских программ и библиотек, `/run` — временное состояние с момента загрузки, `/tmp` — временные файлы, `/proc` и `/sys` — виртуальные представления состояния ядра и устройств. `/root` — домашний каталог администратора, а не корень всей файловой системы `/`. В современных системах `/bin` часто является ссылкой на `/usr/bin`. Разделяйте переменные данные, конфигурацию и исполняемые программы при размещении сервисов.',
'ls -ld / /etc /var /home /proc /sys /usr\nreadlink -f /bin\nstat /etc/passwd',
'`/proc` — не обычный каталог на диске: его файлы генерируются ядром. Не пытайтесь очищать `/proc` для освобождения места.')
task('Карта каталогов','Создайте `/workspace/fhs.txt` и запишите в него пары `etc=config`, `var=data`, `home=users` по одной на строку.',check('Настройки правильно определены',"grep -Fxq 'etc=config' /workspace/fhs.txt"),check('Изменяемые данные определены',"grep -Fxq 'var=data' /workspace/fhs.txt"),check('Домашние каталоги определены',"grep -Fxq 'home=users' /workspace/fhs.txt"))
q('Где по соглашению находятся системные конфигурации?','/etc','/proc','/dev','/tmp',0,'Большинство системных конфигурационных файлов располагают в /etc.')
q('Чем обычно является /proc?','Резервной копией /etc','Виртуальной файловой системой состояния процессов и ядра','Корзиной удалённых файлов','Каталогом установочных ISO',1,'procfs предоставляет состояние ядра и процессов через псевдофайлы.')

module('Файлы и каталоги','Навигация, создание файлов, ссылки, поиск, архивирование и метаданные.')
lesson('Абсолютные и относительные пути','Ошибки пути — одна из самых частых причин неудачных скриптов.',
'Абсолютный путь начинается с `/`, относительный вычисляется от текущего рабочего каталога. `.` означает текущий каталог, `..` — родительский. `~` разворачивается оболочкой в домашний каталог. Команда `cd` встроена в shell, потому что должна менять директорию текущего процесса. `pwd -P` раскрывает символические ссылки, `ls -la` показывает скрытые файлы. Имена с пробелами необходимо заключать в кавычки.',
'cd /workspace\nmkdir -p projects/linux\ncd projects/linux\npwd\ncd ..\nls -la',
'Проверяйте `pwd` перед `rm`, `mv` и относительными путями. Не запускайте удаление по непроверенным переменным.')
task('Дерево проекта','Создайте каталоги `/workspace/company/config`, `/workspace/company/logs` и `/workspace/company/backups`.',check('Каталог конфигурации',"test -d /workspace/company/config"),check('Каталог журналов',"test -d /workspace/company/logs"),check('Каталог резервных копий',"test -d /workspace/company/backups"),hint='mkdir -p сразу создаёт промежуточные каталоги.')
task('Путь с пробелом','Создайте пустой файл `/workspace/company/IT Department/notes.txt`.',check('Файл с пробелом в пути существует',"test -f '/workspace/company/IT Department/notes.txt'"),hint='Путь с пробелом заключите в кавычки.')
q('Что означает `..` в пути?','Домашний каталог','Родительский каталог','Корень ФС','Скрытый файл',1,'Точка с точкой ссылаются на родительский каталог.')
q('Какой путь абсолютный?','../logs','./report','/var/log','~/notes',2,'Начальный слеш обозначает путь от корня файловой системы.')

lesson('Создание, копирование, перенос и удаление','Перед автоматизацией научитесь безопасно изменять файловую структуру.',
'`touch` создаёт файл или обновляет времена. `cp` копирует данные, `cp -a` старается сохранить атрибуты и дерево, `mv` перемещает или переименовывает, `rm` удаляет, `rmdir` удаляет пустые каталоги. `mkdir -p` создаёт родители; `install -m 640 source target` копирует с заданными правами. Для важных изменений сначала применяйте `ls`, `stat` и резервную копию. `rm -rf` не имеет корзины. Перед групповым удалением желательно проверить маску `find ... -print`.',
'cd /workspace\nprintf "alpha\\n" > original.txt\ncp original.txt copy.txt\nmv copy.txt renamed.txt\nstat renamed.txt\nrm -- renamed.txt',
'Для удаления имени, начинающегося с `-`, используйте `rm -- "-name"`. Параметр `-i` полезен при ручной работе, но не заменяет резервную копию.')
task('Скопировать с сохранением источника','В `/workspace/inbox` лежит `report.txt`. Создайте его копию `/workspace/archive/report-2026.txt`, не меняя исходный файл.',check('Копия создана',"test -f /workspace/archive/report-2026.txt"),check('Содержимое совпадает',"cmp -s /workspace/inbox/report.txt /workspace/archive/report-2026.txt"),check('Исходник остался',"test -f /workspace/inbox/report.txt"),setup="mkdir -p /workspace/inbox /workspace/archive; printf 'Server report\\nOK\\n' > /workspace/inbox/report.txt")
q('Что делает `cp -a`?','Очищает архив','Копирует рекурсивно с сохранением атрибутов','Сортирует файлы','Показывает ACL',1,'Архивный режим cp сохраняет типы объектов, метаданные и дерево каталогов насколько возможно.')
q('Почему `rm -rf` опасен?','Он автоматически шифрует диск','Удаление рекурсивное и без запроса подтверждения','Он удаляет только пустые файлы','Он отключает сеть',1,'Опции -r и -f включают рекурсивное и принудительное удаление без интерактивного подтверждения.')

lesson('Чтение и анализ метаданных','Для диагностики полезно видеть фактические размеры, inode, владельцев и времена файлов.',
'`stat` показывает размер, права, владельца, inode, даты доступа и модификации. `file` определяет тип содержимого по сигнатуре, а не по расширению. `du -sh` показывает занятое файловыми объектами пространство, `df -h` — свободные блоки файловой системы. `wc -l` считает переводы строки, не записи логически. `head`, `tail -n`, `less` и `cat` читают содержимое. `tail -f` полезен для динамических журналов на реальной машине.',
'printf "one\\ntwo\\n" > /workspace/a.txt\nstat /workspace/a.txt\nwc -l /workspace/a.txt\nfile /workspace/a.txt\ndu -sh /workspace',
'Различайте `du` (по файлам в каталоге) и `df` (по файловой системе). Файл без завершающего перевода строки влияет на `wc -l`.')
task('Измерить размер и число строк','Для подготовленного `access.log` запишите количество строк (только число) в `/workspace/line-count.txt`.',check('Подсчёт соответствует файлу',"test \"$(tr -d '[:space:]' < /workspace/line-count.txt)\" = \"$(wc -l < /workspace/access.log | tr -d '[:space:]')\""),setup="printf '200 GET /\\n404 GET /bad\\n200 GET /ready\\n503 GET /db\\n' > /workspace/access.log")
q('Что отображает `stat`?','Физические сектора HDD','Метаданные файла','Маршрут до шлюза','Загруженность CPU за час',1,'stat читает сведения inode, включая размер, режим, владельца и времена.')
q('Чем `df` отличается от `du`?','df — место ФС, du — размер файлов и каталогов','df — только сеть, du — память','df — чтение, du — запись','Разницы нет',0,'df сообщает об использовании смонтированной файловой системы, du — об объёме по объектам.')

lesson('Символические и жёсткие ссылки','Ссылки используют для конфигураций, версий релизов и экономного доступа к данным.',
'**Жёсткая ссылка** — второе имя того же inode; пока есть хотя бы одна ссылка, объект сохраняется. **Символическая ссылка** — отдельный inode с текстовым путём к цели; может быть битой и пересекать файловые системы. `ln source hard`, `ln -s target link`, `readlink` и `ls -li` помогают их исследовать. Смена целевого файла может изменить поведение симлинка; для атомарной подмены симлинков удобно использовать временное имя и `mv -T`.',
'printf "release=1\\n" > /workspace/release1\nln /workspace/release1 /workspace/hardlink\nln -s /workspace/release1 /workspace/current\nls -li /workspace/release1 /workspace/hardlink\nreadlink /workspace/current',
'Жёсткие ссылки на каталоги пользователю обычно запрещены. `readlink -f` канонизирует полный путь, а `readlink` выводит значение ссылки.')
task('Симлинк на конфигурацию','Создайте `/workspace/current-config`, символически указывающий на `/workspace/configs/prod.conf`.',check('Это символическая ссылка',"test -L /workspace/current-config"),check('Разрешается в правильный файл',"test \"$(readlink -f /workspace/current-config)\" = /workspace/configs/prod.conf"),setup="mkdir -p /workspace/configs; echo 'port=8080' > /workspace/configs/prod.conf")
q('Что произойдёт с симлинком, если цель исчезнет?','Он всегда копирует содержимое','Может стать битым','Его inode станет inode цели','Файловая система удалит корень',1,'Символическая ссылка хранит путь, который может больше не разрешаться.')
q('Где можно использовать жёсткую ссылку?','На разные ФС','На удалённый HTTP URL','В пределах одной файловой системы','Только на сокеты',2,'Жёсткая ссылка ссылается на inode внутри той же файловой системы.')

lesson('Поиск: find, glob и xargs','Администратор регулярно ищет старые логи, неправильные права и изменённые файлы.',
'Шаблоны shell (`*.log`, `?`) раскрываются до запуска программы. `find` обходит дерево и фильтрует по имени, типу, размеру, возрасту и режиму. `find /var/log -type f -name "*.log"` ищет файлы. `-mtime +7` работает с 24-часовыми интервалами, а не календарными днями. Для безопасной обработки имён с пробелами используйте `-print0 | xargs -0` или `-exec ... {} +`. Сначала выводите кандидатов, потом выполняйте изменение.',
'find /workspace -type f -name "*.log" -print\nfind /workspace -type f -size +1M\nfind /workspace -type f -print0 | xargs -0 -r wc -l',
'`xargs` без `-0` неправильно разбирает имена с пробелами или переводами строк. Не применяйте `find -delete`, пока не проверили критерий.')
task('Список всех LOG-файлов','В `/workspace/records` найдите `.log` файлы (включая вложенные) и запишите только их базовые имена в `/workspace/log-list.txt`, в отсортированном порядке.',check('Список точен',"test \"$(cat /workspace/log-list.txt)\" = \"$(printf 'app.log\\naudit.log')\""),setup="mkdir -p /workspace/records/sub; printf a > /workspace/records/app.log; printf b > /workspace/records/sub/audit.log; printf c > /workspace/records/other.txt",hint='find -name, -printf "%f\\n" и sort.')
q('Зачем `-print0` и `xargs -0`?','Для шифрования','Для корректных имён с пробелами и переводами строки','Для сортировки по inode','Для обхода ACL',1,'Нулевой байт — безопасный разделитель имён файлов в Unix.')
q('Кто раскрывает `*.log` при обычной команде `ls *.log`?','Ядро','Оболочка','systemd','Менеджер пакетов',1,'Глоббинг выполняется оболочкой до запуска ls.')

lesson('Архивы, tar и gzip','Резервирование конфигураций требует понимания формата и восстановления.',
'`tar` упаковывает дерево файлов, сохраняя имена и метаданные, `gzip` сжимает поток. `tar -czf backup.tar.gz -C /workspace project` создаёт архив без абсолютных путей. `tar -tzf` показывает содержимое, `tar -xzf -C destination` распаковывает. `sha256sum` проверяет совпадение байтов при переносе, но не заменяет подписи. Не распаковывайте недоверенный архив с опасными путями и правами в системные каталоги.',
'mkdir -p /workspace/demo\necho hello > /workspace/demo/a.txt\ntar -czf /workspace/demo.tar.gz -C /workspace demo\ntar -tzf /workspace/demo.tar.gz\nsha256sum /workspace/demo.tar.gz',
'Проверяйте восстановление в отдельный каталог. Копия, которую нельзя восстановить, не является проверенным резервным копированием.')
task('Создание резервного архива','Создайте `/workspace/settings.tar.gz`, содержащий каталог `settings` вместе с `app.conf`.',check('Архив существует и не пуст',"test -s /workspace/settings.tar.gz"),check('Нужный файл попал внутрь',"tar -tzf /workspace/settings.tar.gz | grep -Fxq 'settings/app.conf'"),check('В архиве верные данные',"tar -xOzf /workspace/settings.tar.gz settings/app.conf | grep -Fxq 'timeout=30'"),setup="mkdir -p /workspace/settings; printf 'timeout=30\\n' > /workspace/settings/app.conf")
q('Как просмотреть содержимое .tar.gz без распаковки?','tar -tzf','tar -xzf','gzip -d','rm -i',0,'Ключ t выводит список, z использует gzip, f выбирает архив.')
q('Для чего нужен sha256sum?','Назначить владельца','Посчитать криптографический хеш содержимого','Показать процессы','Сменить файловую систему',1,'SHA-256 помогает проверить целостность и совпадение байтов.')

module('Потоки, текст, фильтры','Освойте стандартный ввод/вывод, grep, sed, awk, регулярные выражения.')
lesson('stdin, stdout, stderr и перенаправления','Текстовые потоки — основа командных конвейеров, логирования и скриптов.',
'Файловые дескрипторы: `0` — stdin, `1` — stdout, `2` — stderr. `>` перезаписывает файл, `>>` добавляет; `2>` перенаправляет ошибки. `2>&1` объединяет stderr с текущим stdout и **порядок важен**: `cmd >file 2>&1` и `cmd 2>&1 >file` отличаются. `|` передаёт stdout предыдущей команды в stdin следующей. `tee` одновременно печатает и пишет в файл. `set -o pipefail` в Bash помогает обнаруживать ошибки внутри конвейера.',
'printf "one\\ntwo\\n" | wc -l\nls /missing 2> /workspace/errors.txt\nprintf "ok\\n" | tee /workspace/output.txt\nset -o pipefail',
'`>` уничтожает прежнее содержимое целевого файла. stderr не входит в pipe без специального перенаправления.')
task('Разделить ошибки и результат','Запишите stdout команды `ls /workspace/present /workspace/absent` в `/workspace/out.txt`, а stderr — в `/workspace/err.txt`.',check('stdout содержит существующее имя',"grep -q 'present' /workspace/out.txt"),check('stderr содержит сообщение об отсутствующем',"grep -q 'absent' /workspace/err.txt"),setup="mkdir -p /workspace/present",hint='Примените `> /workspace/out.txt 2> /workspace/err.txt`.')
q('Какой номер у stderr?','0','1','2','3',2,'Дескриптор 2 используется для стандартного потока ошибок.')
q('Что делает оператор >>?','Добавляет в конец файла','Удаляет файл','Соединяет процессы TCP','Меняет owner',0,'Двойной знак больше перенаправляет stdout в режим добавления.')

lesson('grep и регулярные выражения','Отбор событий из огромных журналов значительно ускоряет поиск неисправностей.',
'`grep -n` показывает номера строк, `-i` игнорирует регистр, `-v` инвертирует совпадение, `-E` включает расширенные регулярные выражения, `-F` ищет точный литерал. Регулярные выражения: `^` начало строки, `$` конец, `.` любой символ, `[0-9]` цифра, `+` один или более в ERE. Всегда оборачивайте шаблон одинарными кавычками, чтобы оболочка не раскрыла специальные символы. Применение `grep -r` к бинарным каталогам без ограничений может быть дорогим.',
"""printf "INFO ok\\nERROR disk\\nWARN load\\nERROR net\\n" > /workspace/service.log\ngrep -n '^ERROR' /workspace/service.log\ngrep -E 'ERROR|WARN' /workspace/service.log\ngrep -c '^ERROR' /workspace/service.log""",
'`grep -q` ничего не выводит, а код возврата показывает, было ли совпадение; это удобно для автоматических проверок.')
task('Выделить ошибки','Из подготовленного `/workspace/system.log` сохраните в `/workspace/errors-only.log` только строки, начинающиеся строго с `ERROR`.',check('Результат точен',"test \"$(cat /workspace/errors-only.log)\" = \"$(printf 'ERROR disk\\nERROR api')\""),setup="printf 'INFO boot\\nERROR disk\\nWARN cpu\\nERROR api\\n' > /workspace/system.log")
task('Подсчитать предупреждения','Запишите количество строк `WARN` в `/workspace/warn-count.txt`.',check('Число предупреждений равно 1',"test \"$(tr -d '[:space:]' < /workspace/warn-count.txt)\" = 1"),setup="printf 'INFO boot\\nERROR disk\\nWARN cpu\\nERROR api\\n' > /workspace/system.log")
q('Что означает ^ в начале regex?','Конец имени','Начало строки','Отрицание grep','Начало каталога',1,'В данном контексте ^ привязывает совпадение к началу строки.')
q('Как искать текст буквально, без интерпретации regex?','grep -F','grep -E','grep -P','grep -r',0,'Опция -F включает поиск фиксированных строк.')

lesson('sed и потоковое преобразование','Прежде чем править файл автоматически, полезно понимать замену строк и диапазоны.',
'`sed` читает строки и выполняет правила; `s/old/new/g` заменяет все совпадения в строке, `-n` отключает обычную печать, `p` печатает совпавшие адреса. `sed -i` меняет файл на месте, поэтому на рабочих серверах используйте резервную копию (`-i.bak`) и проверяйте дифф. Разделители в подстановке можно менять (`s|/old|/new|g`). Для сложного парсинга структурированных данных sed ненадёжен: используйте полноценный парсер.',
"""printf "port=80\\nmode=dev\\n" > /workspace/app.ini\nsed 's/port=80/port=8080/' /workspace/app.ini\nsed -n '/^mode=/p' /workspace/app.ini\nsed -i.bak 's/mode=dev/mode=prod/' /workspace/app.ini""",
'Команда `sed -i` часто не выводит результат на экран. После неё читайте файл и проверяйте `diff -u`.')
task('Изменить порт в конфигурации','Замените `port=8000` на `port=9090` в `/workspace/web.conf`, остальные строки сохраняйте.',check('Порт обновлён',"grep -Fxq 'port=9090' /workspace/web.conf"),check('Другие параметры сохранились',"grep -Fxq 'workers=4' /workspace/web.conf"),check('Старая строка исчезла',"! grep -Fxq 'port=8000' /workspace/web.conf"),setup="printf 'port=8000\\nworkers=4\\n' > /workspace/web.conf")
q('Что делает флаг g в s/a/b/g?','Меняет весь файл на b','Заменяет все совпадения в каждой обработанной строке','Добавляет строку после файла','Запускает grep',1,'Флаг g означает глобальную замену в пределах строки.')
q('Как уменьшить риск потери файла при sed -i?','Указать -i.bak','Добавить -n без правил','Запустить от root','Вызвать rm перед sed',0,'-i.bak создаст резервную копию оригинала с суффиксом .bak.')

lesson('awk, поля и CSV','Многие административные отчёты представляют собой колонки текста.',
'`awk` разбивает записи (обычно строки) на поля `$1`, `$2` и т.д. `-F:` задаёт разделитель, `NR` — номер записи, `NF` — число полей. В блоке `BEGIN` можно задать настройки, в `END` — вывести итог. Арифметика и условия позволяют делать компактные отчёты: `awk -F, \'$3>=80 {print $1}\' file`. Простое разбиение по запятой **не является корректным CSV-парсером**, если поддерживаются поля с кавычками; используйте Python `csv` для настоящего CSV.',
"""printf "alice:90\\nbob:75\\n" > /workspace/marks.txt\nawk -F: '$2>=80 {print $1}' /workspace/marks.txt\nawk -F: '{sum+=$2} END{print sum}' /workspace/marks.txt""",
'Заключайте программу awk в одинарные кавычки; иначе Bash развернёт `$1` до того, как увидит его awk.')
task('Сумма столбца','В `/workspace/costs.txt` четыре строки формата `название:цена`. Посчитайте сумму второго поля, запишите одно число в `/workspace/total.txt`.',check('Сумма ровно 160',"test \"$(tr -d '[:space:]' < /workspace/total.txt)\" = 160"),setup="printf 'disk:50\\nram:30\\ncpu:70\\nnet:10\\n' > /workspace/costs.txt")
q('Как в awk обратиться ко второму полю?','$0','$2','NR','NF',1,'Переменная $2 содержит второе поле текущей записи.')
q('Что обозначает NR?','Число полей','Номер текущей записи','Размер файла','Код выхода',1,'NR — накопленный номер прочитанной записи.')

module('Права, пользователи, безопасность файлов','Пользователи, группы, chmod, umask, ACL, sudo.')
lesson('rwx, chmod и umask','Неправильные права — частая причина отказов сервисов и утечек конфигураций.',
'У файла `r` означает чтение, `w` запись, `x` исполнение. У каталога `x` означает возможность прохода по известному имени, `r` — перечисление, `w` вместе с `x` — создание/удаление записей. Три триады прав относятся к владельцу, группе, остальным. Запись `640` означает `rw-r-----`; `750` — `rwxr-x---`. `chmod u+x` добавляет исполнение владельцу, `chmod o-rwx` убирает права у остальных. `umask` вычитает биты из базовых 666 для файлов и 777 для каталогов, не просто арифметически.',
'cd /workspace\necho secret > credentials.txt\nchmod 600 credentials.txt\nstat -c %a credentials.txt\numask\nmkdir private && chmod 700 private',
'Не используйте `chmod 777` как универсальное решение. Каталог с запретом `x` не позволит доступ к файлу, даже если файл читаем.')
task('Защитить конфигурацию','Настройте режим `/workspace/secret.conf` строго `600`.',check('Права установлены 600',"test \"$(stat -c %a /workspace/secret.conf)\" = 600"),setup="printf 'password=dummy\\n' > /workspace/secret.conf; chmod 644 /workspace/secret.conf")
task('Скрипт для группы','Создайте `/workspace/scripts/deploy.sh`, настройте права строго `750`.',check('Файл существует',"test -f /workspace/scripts/deploy.sh"),check('Права 750',"test \"$(stat -c %a /workspace/scripts/deploy.sh)\" = 750"),setup="mkdir -p /workspace/scripts")
q('Что означает x для каталога?','Удаление всех файлов','Возможность проходить через каталог','Автоматическое исполнение файлов','Архивирование',1,'Бит x для директории позволяет разрешать имена внутри неё.')
q('Какие права задаёт chmod 600?','rwx всем','rw владельцу, остальные без прав','r всем и w группе','wx только другим',1,'Шестёрка даёт владельцу r+w, нули лишают группу и остальных доступа.')

lesson('UID, GID, useradd и passwd','Для разграничения доступа важны реальные идентификаторы, а не только имена.',
'Пользователи описаны в `/etc/passwd`, группы — в `/etc/group`; хеши паролей обычно в `/etc/shadow`. `id`, `getent passwd name`, `groups` проверяют учётки. `useradd -m -s /bin/bash name` создаёт пользователя и домашний каталог, `usermod -aG group user` добавляет дополнительную группу **без стирания прежних**. На продуктивных серверах политики управления пользователями лучше описывать в Ansible. В контейнерной лаборатории новые UID существуют только внутри её пространства имён.',
'id\ngetent passwd root\ngetent group root\nuseradd -m -s /bin/bash student1\nid student1',
'Будьте аккуратны с `usermod -G`: без `-a` список дополнительных групп заменяется полностью.')
task('Сервисная учётка','Создайте пользователя `svcacademy` с домашним каталогом и оболочкой `/bin/bash`.',check('Учётка появилась',"id svcacademy >/dev/null 2>&1"),check('Домашний каталог есть',"test -d /home/svcacademy"),check('Оболочка bash',"test \"$(getent passwd svcacademy | cut -d: -f7)\" = /bin/bash"))
q('Где обычно хранятся хеши локальных паролей?','/etc/hosts','/etc/shadow','/proc/cpuinfo','/var/tmp',1,'Привилегированный файл /etc/shadow содержит данные проверки локальных паролей.')
q('Почему нужен -a в usermod -aG?','Добавляет группу, не удаляя другие вторичные группы','Включает аудит','Задаёт ACL','Отменяет пароль',0,'-a означает append, то есть добавление к существующему набору групп.')

lesson('Группы, владельцы и chown','Обычно приложению нужен доступ через группу, а не широкие права для всех.',
'`chown user:group file` назначает владельца и группу, `chgrp group file` — только группу. `id -nG` показывает названия групп; новая групповая принадлежность обычно применяется после нового входа. `chmod g+s directory` задаёт setgid для каталога — новые файлы чаще наследуют его группу. Рекурсивные операции меняют много объектов, поэтому сначала оцените дерево с `find` и `ls -l`. Для совместных папок иногда требуются ACL, поскольку обычной тройки rwx не хватает.',
'groupadd appteam\nmkdir -p /workspace/shared\nchgrp appteam /workspace/shared\nchmod 2770 /workspace/shared\nstat -c "%U %G %a" /workspace/shared',
'Если rootless-контейнер не имеет достаточного диапазона subuid/subgid, пользовательские UID могут быть недоступны; проверьте конфигурацию раннера.')
task('Совместный каталог команды','Создайте группу `opsacademy` и каталог `/workspace/ops` с группой `opsacademy` и режимом `2770`.',check('Группа существует',"getent group opsacademy >/dev/null"),check('Группа каталога задана',"test \"$(stat -c %G /workspace/ops)\" = opsacademy"),check('Режим с setgid 2770',"test \"$(stat -c %a /workspace/ops)\" = 2770"))
q('Что делает chown?','Меняет DNS','Устанавливает владельца или группу файла','Перезапускает daemon','Меняет PATH',1,'chown работает с UID/GID, хранящимися в метаданных inode.')
q('Зачем setgid на общем каталоге?','Побудить новые файлы наследовать группу каталога','Запретить чтение','Сжать все файлы','Ускорить inode',0,'Для обычного общего каталога setgid помогает сохранять одну групповую принадлежность.')

lesson('ACL и sudo: делегирование без 777','Когда rwx недостаточно, ACL позволяют давать точечный доступ.',
'POSIX ACL добавляют правила для конкретных пользователей и групп. `getfacl file`, `setfacl -m u:alice:rw file`, `setfacl -d -m g:team:rwX dir` управляют текущими и наследуемыми правилами. ACL mask может ограничить эффективные права. `sudo` предоставляет привилегированные команды по policy `/etc/sudoers`; редактируйте через `visudo`, а не прямым `echo` в боевом окружении. Принцип наименьших привилегий требует выдавать только необходимые действия. Для сервисных аккаунтов чаще достаточно ACL или групп, а не полного root-доступа.',
'getfacl /workspace\n# На реальном сервере:\n# sudo visudo -f /etc/sudoers.d/backup-operator\n# sudo -l',
'Контейнер лаборатории не является площадкой для полноценных заданий по PAM, polkit и интеграции AD. Эти упражнения выполняют в ВМ.',vm=True)
q('Как проверить ACL файла?','getfacl','lsmod','iptables','rpm -qi',0,'getfacl показывает расширенные списки управления доступом.')
q('Почему sudoers редактируют через visudo?','Для проверки синтаксиса до установки изменений','Для удаления root','Для включения сети','Для генерации SSL',0,'visudo блокирует файл на время правки и проверяет синтаксис, уменьшая риск потери sudo.')

module('Процессы, пакеты, службы','Жизненный цикл процессов, сигналы, systemd, apt и dnf.')
lesson('Процессы, PID и сигналы','Без умения работать с процессами невозможно диагностировать зависший сервис.',
'Каждый процесс имеет PID, PPID, владельца и состояние. `ps aux`, `ps -ef`, `pstree`, `top` дают разные представления. `kill -TERM PID` просит завершиться корректно; `kill -KILL` не даёт обработать сигнал и является последним средством. `pgrep -af pattern` ищет процесс по командной строке. Короткоживущие процессы могут завершиться до диагностики. Zombie-процесс уже завершился; ожидать должен его родитель.',
'ps -eo pid,ppid,user,stat,comm | head\nsleep 120 &\njobpid=$!\nps -p "$jobpid" -o pid,stat,cmd\nkill -TERM "$jobpid"',
'Не отправляйте `kill -9` вслепую: сначала убедитесь, что PID относится к нужному процессу и исследуйте последствия.')
task('Запустить и обнаружить процесс','Запустите в терминале фоновый процесс `sleep 600`; его PID сохраните в `/workspace/sleep.pid`.',check('PID — число',"grep -Eq '^[0-9]+$' /workspace/sleep.pid"),check('Процесс существует и является sleep',"pid=$(cat /workspace/sleep.pid); test \"$(cat /proc/$pid/comm 2>/dev/null)\" = sleep"),hint='sleep 600 & ; echo $! > /workspace/sleep.pid')
q('Какой сигнал обычно позволяет приложению корректно завершиться?','SIGKILL','SIGTERM','SIGSTOP','SIGCONT',1,'SIGTERM может быть перехвачен приложением для освобождения ресурсов.')
q('Что показывает PPID?','Процент памяти','Идентификатор родительского процесса','Имя репозитория','Номер сетевого порта',1,'PPID — PID процесса, создавшего текущий процесс.')

lesson('Фоновые задания и приоритеты','Длительные команды следует запускать так, чтобы не терять контроль за их жизненным циклом.',
'`&` запускает команду в фоне, `$!` возвращает PID последнего фонового задания, `jobs`, `fg`, `bg` управляют заданиями текущей оболочки. `nohup` игнорирует SIGHUP, но для сервисов лучше использовать systemd unit. `nice -n 10` понижает приоритет планировщика; `renice` меняет niceness уже запущенного процесса. Фоновые задачи в учебном контейнере не переживут его сброс.',
'sleep 20 &\njobs -l\nwait $!\nnice -n 10 sleep 1',
'Не путайте jobs оболочки и systemd-сервисы: первые привязаны к сессии shell, вторые управляются менеджером сервисов.')
task('Сценарий с фоновым запуском','Сделайте исполняемый `/workspace/background.sh`, запускающий `sleep 2` в фоне и записывающий PID в `/workspace/bg.pid`.',check('Скрипт исполняемый',"test -x /workspace/background.sh"),check('Скрипт запускается и сохраняет PID',"/workspace/background.sh && grep -Eq '^[0-9]+$' /workspace/bg.pid"),hint='После команды sleep 2 & используйте $!.')
q('Что содержит $! в bash?','Текущий пароль','PID последнего фонового задания','Процент загрузки','Код выхода последней команды',1,'Специальный параметр $! хранит идентификатор последнего асинхронного процесса.')
q('Что означает увеличение nice с 0 до 10?','Обычно снижает приоритет планирования','Всегда увеличивает память','Отключает процесс','Включает sudo',0,'Большее значение nice означает меньшую относительную приоритетность процесса.')

lesson('APT и dpkg в Debian/Ubuntu','Разбирайтесь в репозиториях, зависимостях и состояниях пакетов.',
'`apt update` обновляет индексы пакетов, `apt upgrade` обновляет установленные пакеты; `apt install pkg` устанавливает пакет с разрешением зависимостей. `apt-cache policy` показывает кандидатов и репозитории. Низкоуровневый `dpkg -l`, `dpkg -L pkg`, `dpkg -S path` работают с локальной базой. Ошибки могут означать отсутствие индекса, поломанные зависимости, блокировку менеджера пакетов или некорректный источник. В учебных лабораториях сеть намеренно отключена: внешнюю установку пакетов делайте только в отдельной ВМ.',
'cat /etc/os-release\ndpkg-query -W bash\ndpkg -L coreutils | head\napt-cache policy bash',
'Для Ubuntu/Debian не смешивайте произвольные чужие репозитории. Не удаляйте lock-файлы пакетного менеджера, пока не выяснили, какой процесс удерживает блокировку.',vm=True)
task('Найти версию пакета','В Ubuntu лаборатории запишите установленную версию bash в `/workspace/bash-version.txt`, только строку версии.',check('Версия равна установленной',"test \"$(cat /workspace/bash-version.txt)\" = \"$(dpkg-query -W -f='${Version}' bash)\""),hint="dpkg-query -W -f='${Version}' bash")
q('Что делает apt update?','Всегда обновляет ядро','Обновляет локальные индексы пакетов','Отключает sudo','Перезагружает сервер',1,'apt update обновляет метаданные доступных пакетов, но не устанавливает обновления.')
q('Как узнать, какой пакет установил файл?','dpkg -S /path','df -S /path','uname -S','ip route',0,'dpkg -S ищет владельца указанного пути среди установленных пакетов.')

lesson('DNF и RPM в AlmaLinux/RHEL','RPM-дистрибутивы похожи по целям, но отличаются инструментами.',
'RPM — формат и база установленных пакетов. `rpm -q bash` проверяет установленный пакет, `rpm -ql` перечисляет файлы, `rpm -qf /usr/bin/bash` определяет владельца пути. `dnf install`, `dnf update`, `dnf repolist` управляют пакетами и репозиториями с разрешением зависимостей. AlmaLinux относится к RHEL-совместимому семейству, поэтому имена пакетов могут отличаться от Debian. Не используйте apt на AlmaLinux или dnf на Debian.',
'cat /etc/redhat-release\nrpm -q bash\nrpm -ql bash | head\nrpm -qf /usr/bin/bash\ndnf repolist',
'Сеть в лаборатории отключена. Подключение внутренних корпоративных зеркал и GPG-ключей должно выполняться отдельно в тестовой ВМ.',vm=True)
task('Инвентаризация RPM','В AlmaLinux лаборатории сохраните точный результат `rpm -q bash` в `/workspace/rpm-bash.txt`.',check('Результат совпадает с rpm',"test \"$(cat /workspace/rpm-bash.txt)\" = \"$(rpm -q bash)\""),distro='alma')
q('Какой менеджер пакетов стандартен для AlmaLinux 9?','apt','pacman','dnf','apk',2,'Семейство RHEL использует DNF для разрешения зависимостей RPM-пакетов.')
q('Что проверяет rpm -q bash?','Наличие установленного RPM-пакета bash','Сетевой шлюз','Содержимое /home','Состояние systemd',0,'Запрос rpm -q возвращает сведения об установленном пакете из RPM database.')

lesson('systemd: units, targets, dependencies','Чтобы служба переживала перезагрузку, нужны правильный unit и диагностика.',
'На большинстве современных полноценных серверов Linux PID 1 — systemd. Unit `.service` определяет `ExecStart`, `User`, перезапуск и зависимости; `.timer` — расписание; `.mount` — монтирование. `systemctl status nginx`, `is-enabled`, `enable --now` показывают разные аспекты: `enable` включает автозапуск, `start` запускает сейчас. После изменения unit применяют `systemctl daemon-reload`. Журнал смотрят через `journalctl -u NAME -b`. Для зависимостей `After=` определяет порядок, но само по себе не подтягивает другую службу — это делает `Wants=`/`Requires=`.',
'systemctl status ssh\nsystemctl cat ssh\nsystemctl list-unit-files --type=service\nsystemctl daemon-reload\njournalctl -u ssh -b --no-pager | tail',
'Встроенный контейнер не запускает полноценный systemd как PID 1. Разворачивайте это упражнение в тестовой ВМ, например Debian 13, чтобы действительно проверять автозапуск и рестарты.',vm=True)
task('Написать unit-файл','Создайте `/workspace/academy.service` с секциями `[Unit]`, `[Service]`, `[Install]`; задайте `ExecStart=/usr/bin/sleep infinity` и `WantedBy=multi-user.target`. Это проверка конфигурации, не запуск unit в контейнере.',check('Есть секция Unit',"grep -Fxq '[Unit]' /workspace/academy.service"),check('Команда ExecStart',"grep -Fxq 'ExecStart=/usr/bin/sleep infinity' /workspace/academy.service"),check('Указана цель автозапуска',"grep -Fxq 'WantedBy=multi-user.target' /workspace/academy.service"))
q('Чем enable отличается от start?','enable — загрузка unit из сети','enable — автозапуск при следующих загрузках, start — текущий запуск','Это синонимы','start всегда перезагружает сервер',1,'systemctl enable создаёт связи для автоматического запуска, а start запускает unit сейчас.')
q('Когда нужен daemon-reload?','После изменения unit-файла','После любого ls','После изменения PATH пользователя','После вызова grep',0,'systemd должен перечитать изменённые определения unit-ов.')

module('Диски, память, загрузка','Мониторинг памяти, файловых систем, разделы и LVM в отдельной VM.')
lesson('CPU, память и OOM','Диагностика начинается с различия между нагрузкой, загрузкой CPU и памятью.',
'`free -h` показывает память, buffers/cache и доступную память, `uptime` — load average и аптайм, `top` — активные процессы, `/proc/meminfo` — показатели ядра. Load average включает выполняемые и обычно непрерываемо ожидающие задачи, поэтому 8.0 не равняется 800% CPU без знания количества ядер. OOM killer завершает процессы при дефиците памяти и ограничениях cgroups; в контейнере есть лимит памяти, который может отличаться от хостовой. Для VM анализируйте журналы kernel и статистику swap.',
'free -h\nuptime\ncat /proc/meminfo | head\nps -eo pid,%cpu,%mem,comm --sort=-%mem | head',
'Нельзя делать вывод «память закончилась» только из малого free: Linux активно использует кэш.')
task('Число процессоров','Сохраните значение `getconf _NPROCESSORS_ONLN` в `/workspace/cpus.txt`.',check('Правильное положительное количество',"test \"$(cat /workspace/cpus.txt)\" = \"$(getconf _NPROCESSORS_ONLN)\""))
q('О чём говорит load average?','Это только процент CPU','Это усреднённая очередь выполнения/ожидания задач','Это температура CPU','Это число пользователей',1,'Метрика load average отражает ожидающие и выполняемые задачи, а не процент загрузки.')
q('Какой показатель free полезен для оценки доступной памяти?','available','shared','Swap total','buffers как отдельная память',0,'available учитывает память, которую ядро может выделить без сильного свопинга.')

lesson('Файловые системы и inode','«Нет места» может означать исчерпание блоков или inode.',
'`df -h` показывает блоки; `df -i` количество свободных inode, `du -xhd1 /var` помогает искать крупные каталоги. ext4 и XFS — распространённые файловые системы на Linux; их инструменты создания и восстановления отличаются. Удалённый, но всё ещё открытый процессом файл может продолжать занимать место: помогает `lsof +L1` на полной ВМ. `mount` и `findmnt` показывают точки монтирования. В лаборатории `df` отображает файловую систему контейнера/хоста, поэтому упражнения ограничены отчётами, а не управлением реальными разделами.',
'df -h /workspace\ndf -i /workspace\ndu -sh /workspace\nstat -c %i /workspace',
'Не применяйте fsck к смонтированному разделу вслепую. Для ремонта нужен безопасный режим и резервная копия.',vm=True)
task('Отчёт о диске','Запишите в `/workspace/fs-report.txt` результат `df -h /workspace` вместе с заголовком.',check('Есть поле Filesystem',"grep -q '^Filesystem' /workspace/fs-report.txt"),check('Есть строка точки монтирования',"test \"$(wc -l < /workspace/fs-report.txt)\" -ge 2"))
q('Что показывает df -i?','Свободные и занятые inode','IP-адреса','Ошибки apt','Список пользователей',0,'Ключ -i переключает df на учёт inode.')
q('Почему удалённый файл может занимать место?','Есть открытый файловый дескриптор у процесса','Любой файл навсегда хранится в RAM','Потому что grep кэширует имена','Из-за имени файла',0,'Данные могут оставаться выделенными, пока процесс держит открытый inode.')

lesson('Разделы, GPT, UUID, fstab','Настройки хранилища делайте через стабильные идентификаторы, проверяя восстановление.',
'`lsblk -f` показывает устройства, файловые системы и UUID. `blkid` читает идентификаторы; `findmnt` показывает активное монтирование. `/etc/fstab` задаёт постоянные монтирования. Вместо нестабильного `/dev/sdb1` часто используют `UUID=...`. Опции `nofail` и `x-systemd.device-timeout=` могут быть важны для необязательных дисков. Изменения проверяют `findmnt --verify` и `mount -a`, но последняя команда реально меняет монтирования. Разметка `parted`, `fdisk`, `mkfs` потенциально уничтожает данные и должна происходить только на добавленном пустом диске отдельной ВМ.',
'lsblk -f\nblkid\nfindmnt /\ncat /etc/fstab\n# В ВМ: sudo findmnt --verify',
'Контейнер не получает доступ к блочным устройствам хоста. Не нужно давать ему `--privileged` только ради этих заданий.',vm=True)
task('Пример fstab','Создайте `/workspace/example.fstab` со строкой для `/dev/disk/by-uuid/DEMO-UUID`, точки `/data`, типа `ext4`, опций `defaults,nofail`, последних двух полей `0 2`.',check('Есть корректная строка',"grep -Eq '^/dev/disk/by-uuid/DEMO-UUID[[:space:]]+/data[[:space:]]+ext4[[:space:]]+defaults,nofail[[:space:]]+0[[:space:]]+2$' /workspace/example.fstab"))
q('Зачем UUID в /etc/fstab?','Чтобы снизить зависимость от порядка имён /dev/sdX','Чтобы всегда включить swap','Чтобы установить GRUB','Для шифрования файла',0,'UUID устойчивее, чем имена блочных устройств, порядок которых может меняться.')
q('Почему нельзя запускать mkfs по рабочему разделу?','Он меняет права пользователя','Он создаёт новую файловую систему и может уничтожить существующие данные','Он перезапускает ssh','Он изменяет DNS',1,'mkfs форматирует выбранное устройство, приводя к потере прежней структуры данных.')

lesson('Загрузка, GRUB, initramfs и rescue','Понимайте последовательность загрузки, чтобы восстанавливать сервер после сбоя.',
'После firmware BIOS/UEFI загрузчик (обычно GRUB) выбирает ядро и initramfs. Ядро инициализирует устройства и передаёт управление PID 1, который запускает системные сервисы. При сломанном fstab, initramfs, драйверах или загрузчике может понадобиться rescue/live ISO. Диагностика включает `journalctl -b -1`, `systemctl --failed`, `dmesg -T`, проверку UUID и запись консоли. Для учебной практики полезно сделать снапшот ВМ, намеренно испортить тестовый unit и восстановить загрузку. Никогда не экспериментируйте с GRUB в продуктивной системе.',
'uname -r\nls /boot\ncat /proc/cmdline\n# В ВМ: journalctl -b -1\n# В ВМ: systemctl --failed',
'Тема требует отдельной VM с консолью гипервизора и снапшотом. Контейнер не симулирует BIOS/UEFI и перезапуск собственного ядра.',vm=True)
q('Что делает initramfs?','Обеспечивает раннее окружение для подготовки корневой ФС','Выполняет скрипты Git','Хранит домашние каталоги','Меняет DNS в браузере',0,'initramfs помогает ядру получить доступ к корневой файловой системе до перехода в основную ОС.')
q('Что полезно для анализа предыдущей загрузки systemd?','journalctl -b -1','pwd -P','grep --help','mkdir -p',0,'Опция -b -1 выбирает журнал предыдущей загрузки, если он сохранился.')

module('Сети и удалённый доступ','IP, маршруты, DNS, SSH, диагностика TCP и сетевой фильтр.')
lesson('IP-адрес, маска, шлюз и маршрут','Сетевой доступ определяется интерфейсом, адресацией, маршрутизацией и фильтрацией.',
'IPv4-адрес вместе с префиксом CIDR определяет сеть. Пример `192.168.10.20/24` — обычно сеть `192.168.10.0/24` и 254 потенциально пригодных для хостов адреса в стандартной подсети. `ip -br addr`, `ip route`, `ip route get 1.1.1.1` помогают исследовать реальную маршрутизацию. Default route задаёт следующий узел для незнакомых сетей. `127.0.0.1` — loopback. В контейнере занятия IP ограничены, потому что сетевой namespace отключён от внешней сети.',
'ip -br addr\nip route\nip route show table main\nip -4 addr show lo',
'Не подменяйте маршруты рабочего хоста ради упражнения. Удалённый SSH может исчезнуть после изменения интерфейса или default route.',vm=True)
task('Объяснить loopback','Создайте `/workspace/loopback.txt`, запишите IP-адрес `127.0.0.1` и имя интерфейса `lo` по отдельным строкам.',check('IP указан',"grep -Fxq '127.0.0.1' /workspace/loopback.txt"),check('Интерфейс указан',"grep -Fxq 'lo' /workspace/loopback.txt"))
q('Зачем default route?','Маршрут к сетям без более конкретного совпадения','Чтобы задать пароль root','Чтобы включить swap','Чтобы установить bash',0,'Маршрут по умолчанию используется, когда более специфичный маршрут не найден.')
q('Что означает /24 для IPv4?','24 бита адреса сети','24 порта TCP','24 Ethernet-кадра','24 DNS-записи',0,'CIDR-префикс 24 задаёт длину сетевой части адреса в битах.')

lesson('DNS, resolver, hosts и поиск ошибок','DNS и маршрутизация — независимые звенья, и их нужно проверять отдельно.',
'Resolver преобразует имя в адрес через configured DNS. `/etc/hosts` обеспечивает локальные статические соответствия; `/etc/resolv.conf` часто управляется systemd-resolved, NetworkManager или другим сетевым менеджером, поэтому ручная правка может не сохраниться. `getent hosts name`, `resolvectl status`, `dig`, `nslookup` помогают диагностике в полной ВМ. При ошибках уточняйте: имя не разрешается, IP недостижим или порт заблокирован. Корпоративный DNS может обслуживать приватные доменные зоны.',
'cat /etc/hosts\ncat /etc/resolv.conf\ngetent hosts localhost\n# В ВМ: resolvectl status\n# В ВМ: dig +short example.org',
'Встроенной лаборатории отключён внешний DNS. Для изменяемых файлов тренируйтесь на копии hosts, не затрагивая реальные корпоративные записи.',vm=True)
task('Создать учебный hosts','Создайте `/workspace/hosts.lab` с корректной строкой `192.0.2.10 app.lab.local`.',check('Учебная запись DNS задана',"grep -Eq '^192\\.0\\.2\\.10[[:space:]]+app\\.lab\\.local$' /workspace/hosts.lab"))
q('Что делает /etc/hosts?','Локально связывает имена и IP','Сохраняет DNS-зоны всего мира','Управляет GRUB','Содержит системные пароли',0,'Система может использовать /etc/hosts для локального разрешения имён.')
q('Что проверить первым при ошибке «имя не найдено»?','Разрешается ли DNS-имя','Размер swap','Версию tar','Группу владельца',0,'Нужно отделить проблему разрешения имён от достижимости IP и доступности порта.')

lesson('TCP, UDP и проверка портов','«Сервер пингуется» не означает, что приложение доступно по TCP.',
'ICMP echo (`ping`) проверяет ответы на диагностический протокол, но фильтрация ICMP не доказывает недоступность TCP. `ss -lntup` показывает слушающие сокеты, `curl -I` проверяет HTTP, `nc -vz host port` — возможность TCP-соединения, `traceroute`/`tracepath` — направление пути с ограничениями. UDP не создаёт постоянное соединение как TCP. При сетевых проблемах проверяйте четыре уровня: имя, маршрут, порт, прикладной ответ. Тестовый стенд намеренно не открывает порты во внутреннюю сеть.',
'ss -lntu\n# В ВМ с учебным веб-сервером:\n# curl -v http://127.0.0.1:8080/\n# nc -vz 127.0.0.1 8080',
'Никогда не делайте порт-сканирование предприятия без согласования. Для урока используйте собственную VM.',vm=True)
task('Сводка прослушивания','Сохраните вывод `ss -lntu` в `/workspace/sockets.txt`.',check('Есть колонка Local Address',"grep -Eq 'Local Address|Local' /workspace/sockets.txt"),check('Файл не пуст',"test -s /workspace/sockets.txt"))
q('Что показывает ss -lnt?','Слушающие TCP-сокеты без разрешения имён','Историю загрузок','Список sudoers','Пакеты apt',0,'-l выбирает слушающие, -n численные, -t TCP-сокеты.')
q('Можно ли считать сервер недоступным лишь потому, что ping не отвечает?','Да, всегда','Нет, ICMP может фильтроваться отдельно от TCP','Да, DNS обязательно сломан','Нет, TCP не использует IP',1,'ICMP echo может быть заблокирован при сохранении прикладной доступности TCP.')

lesson('SSH, ключи, sshd и безопасный доступ','SSH — базовый способ администрировать Unix-серверы удалённо.',
'Публичный ключ можно размещать в `~/.ssh/authorized_keys`, приватный ключ хранится у клиента и не передаётся. `ssh-keygen -t ed25519`, `ssh -i key user@host`, `ssh -v` используются для создания и диагностики подключения. Права каталога `.ssh` обычно `700`, `authorized_keys` — `600`; OpenSSH проверяет строгие права в типичной конфигурации. `sshd -t` проверяет синтаксис конфигурации; изменяя `PasswordAuthentication` или `PermitRootLogin`, сохраняйте вторую открытую сессию и доступ к консоли.',
'ls -ld ~/.ssh 2>/dev/null || true\nssh -V\n# На тестовой VM: sudo sshd -t\n# С клиента: ssh -v -i ~/.ssh/id_ed25519 user@host',
'Не копируйте приватные ключи в браузерную лабораторию. Для реального SSH нужен отдельный учебный сервер с контролируемым сетевым доступом.',vm=True)
task('Права каталога ключей','Создайте `/workspace/sshkeys/.ssh/authorized_keys` и установите для каталога `.ssh` права `700`, для файла `600`.',check('Права каталога 700',"test \"$(stat -c %a /workspace/sshkeys/.ssh)\" = 700"),check('Права файла 600',"test \"$(stat -c %a /workspace/sshkeys/.ssh/authorized_keys)\" = 600"))
q('Что требуется держать в секрете при SSH-авторизации по ключу?','Публичный ключ','Приватный ключ','Имя сервера','Порт 22 как число',1,'Знание приватного ключа позволяет имитировать владельца ключевой пары.')
q('Чем проверить синтаксис конфигурации sshd?','sshd -t','ssh -k','ss -p','uname -a',0,'sshd -t проверяет конфигурацию демона SSH без старта новой службы.')

module('Bash и автоматизация','Переменные, условия, циклы, функции, парсинг и надёжные скрипты.')
lesson('Переменные, кавычки и параметры скрипта','Почти все ошибки shell-автоматизации связаны с некорректными кавычками и непроверенными данными.',
'Переменная определяется `name=value` без пробелов, читается как `$name` или `${name}`. Экспортированные переменные наследуются дочерними процессами. Параметры скрипта: `$0` имя, `$1` первый аргумент, `$@` все аргументы, `$#` количество. Двойные кавычки сохраняют пробелы в значении как один аргумент: `"$file"`. В `"$@"` каждый исходный параметр остаётся отдельным. `$(command)` позволяет получить stdout подкоманды. `read -r` читает строку, не интерпретируя обратные слеши.',
'PROJECT="My Team"\nprintf "Project: %s\\n" "$PROJECT"\nexport PROJECT\nprintf "args: %s\\n" "$#"\ndate_today=$(date +%F)',
'В Bash нет пробелов около `=` в присваивании. Не используйте непроцитированную переменную для путей с пробелами.')
task('Скрипт с аргументом','Создайте исполняемый `/workspace/greet.sh`, который печатает `Hello, NAME` при вызове `./greet.sh NAME`.',check('Результат для alice',"test \"$(/workspace/greet.sh alice)\" = 'Hello, alice'"),check('Результат для ops team',"test \"$(/workspace/greet.sh 'ops team')\" = 'Hello, ops team'"))
q('Почему почти всегда пишут "$file"?','Чтобы сохранить пробелы и избежать нежелательного word splitting','Чтобы ускорить CPU','Чтобы включить sudo','Чтобы создать каталог',0,'Кавычки не дают shell разделять значение переменной на несколько аргументов.')
q('Что содержит $# внутри скрипта?','PID скрипта','Количество позиционных аргументов','Последний код возврата','Путь к bash',1,'Специальная переменная $# задаёт число переданных параметров.')

lesson('Условия if, test и сравнения','Условия позволяют останавливать автоматизацию при некорректном состоянии.',
'`[[ -f path ]]` проверяет обычный файл, `-d` каталог, `-e` существование, `-n` непустую строку. Для строк используйте `==` в `[[ ]]`, для чисел `-eq`, `-gt`, `-lt` в `[ ]` или `(( ))`. Конструкция `if ...; then ...; elif ...; else ...; fi` зависит от кода возврата теста. Правильное поведение при отсутствии файла обычно лучше явно указать, чем позволить следующей команде создать некорректный результат.',
'if [[ -f /workspace/app.conf ]]; then\n  echo found\nelse\n  echo missing\nfi\nn=10\nif (( n > 5 )); then echo big; fi',
'`[ ... ]` — команда test; для неё важны пробелы. В bash `[[ ... ]]` безопаснее для проверок строк и шаблонов.')
task('Проверка файла','Создайте исполняемый `/workspace/checkfile.sh`: при существовании файла из `$1` печатает `FOUND`, иначе `MISSING`.',check('Верная ветка для существующего',"touch /workspace/existing.test; test \"$(/workspace/checkfile.sh /workspace/existing.test)\" = FOUND"),check('Верная ветка для отсутствующего',"test \"$(/workspace/checkfile.sh /workspace/nonexistent.test)\" = MISSING"))
q('Как проверить обычный файл в bash?','[[ -f "$p" ]]','[[ -d "$p" ]]','[[ -z -f ]]','[[ -x -d ]]',0,'-f проверяет существование обычного файла.')
q('Какая конструкция используется для арифметики Bash?','(( n > 5 ))','grep --if','tar -f','$PATH -eq',0,'Двойные круглые скобки позволяют вычислять арифметические выражения.')

lesson('Циклы for, while и обработка имён','Надёжный цикл должен обрабатывать пробелы и завершаться при ошибке.',
'`for item in ...; do ...; done` перебирает элементы списка. `while IFS= read -r line; do ...; done < file` читает строки без потери пробелов и обратных слешей. Для имён файлов надёжнее нулевые разделители с `find ... -print0` и `read -d ""`. `break` завершает цикл, `continue` пропускает шаг. Будьте осторожны с конвейером в `while`: во многих оболочках цикл может исполняться в дочернем процессе, и изменения переменных снаружи пропадут.',
'for n in 1 2 3; do printf "%s\\n" "$n"; done\nwhile IFS= read -r line; do\n  printf "read:%s\\n" "$line"\ndone < /etc/os-release',
'Не используйте `for f in $(ls)` для имён файлов. Такая конструкция ломается на пробелах и спецсимволах.')
task('Генератор отчётов','Сделайте исполняемый `/workspace/sequence.sh`, который выводит ровно пять строк `item-1` ... `item-5`.',check('Все пять строк точны',"test \"$(/workspace/sequence.sh)\" = \"$(printf 'item-1\\nitem-2\\nitem-3\\nitem-4\\nitem-5')\""))
q('Как корректно читать строки из файла?','while IFS= read -r line','for line in $(cat file)','while ls file','cat -f file',0,'IFS= read -r сохраняет ведущие пробелы и обратные слеши.')
q('Что делает continue?','Завершает весь shell','Переходит к следующей итерации','Вызывает sudo','Удаляет файл',1,'continue пропускает остаток тела текущей итерации цикла.')

lesson('Функции, ошибки и строгий режим','Скрипты, которые лишь «работают у автора», опасны в эксплуатации.',
'Функция Bash `name() { ...; }` группирует команды и возвращает код через `return`. `set -euo pipefail` полезен для раннего обнаружения ошибок, но `set -e` имеет исключения (в условиях, составных командах); нельзя считать его заменой обработке ошибок. `trap cleanup EXIT` освобождает временные ресурсы. `mktemp -d` создаёт приватный временный каталог. Логи добавляйте с timestamp, в stderr направляйте ошибки, секреты не печатайте. Для критичных операций предусмотрите dry-run.',
"""set -euo pipefail\nlog() { printf "%s %s\\n" "$(date -Is)" "$*"; }\nwork=$(mktemp -d)\ntrap 'rm -rf -- "$work"' EXIT\nlog "starting"\n""",
'`set -e` не универсальный перехватчик исключений. Проверяйте возврат команд в логических выражениях отдельно.')
task('Функция суммирования','Создайте `/workspace/sum.sh`: с двумя целыми аргументами выводит их сумму и завершается 0.',check('Сумма 7 и 15 равна 22',"test \"$(bash /workspace/sum.sh 7 15)\" = 22"),check('Сумма -3 и 9 равна 6',"test \"$(bash /workspace/sum.sh -3 9)\" = 6"))
q('Для чего полезен trap ... EXIT?','Для уборки временных ресурсов при выходе','Для настройки PATH','Для смены файловой системы','Для DNS-запроса',0,'Обработчик EXIT выполняется при завершении shell и помогает выполнять cleanup.')
q('Что добавляет pipefail?','Успех pipe зависит не только от последнего шага','Всегда запускает команды параллельно','Удаляет pipe','Заменяет stderr',0,'С pipefail конвейер может вернуть ошибку одного из предыдущих элементов.')

lesson('Планировщики cron и systemd timer','Автоматизация должна иметь расписание, логирование и контроль ошибок.',
'Классическая строка cron содержит пять полей: минута, час, день месяца, месяц, день недели, затем команду. Запуск `0 3 * * *` — ежедневно в 03:00 по времени планировщика. Не рассчитывайте на PATH интерактивного пользователя: задавайте абсолютные пути. systemd timer поддерживает `OnCalendar=`, `Persistent=`, зависимости от service unit, и диагностируется через journalctl. В контейнере мы проверяем корректность примера расписания; фактический cron и systemd timers — только в отдельной ВМ.',
'crontab -l\n# Пример:\n# 0 3 * * * /usr/local/sbin/backup.sh >> /var/log/backup.log 2>&1\n# В ВМ: systemctl list-timers --all',
'Контейнер без init не гарантирует работу daemon cron. Для проверки перезапуска, логов и времени используйте отдельный VM-стенд.',vm=True)
task('Расписание резервного копирования','Сохраните в `/workspace/backup.cron` строку запуска `/usr/local/bin/backup.sh` каждый день в 02:30.',check('Корректное cron-расписание',"grep -Eq '^30[[:space:]]+2[[:space:]]+\\*[[:space:]]+\\*[[:space:]]+\\*[[:space:]]+/usr/local/bin/backup\\.sh([[:space:]]|$)' /workspace/backup.cron"))
q('Сколько полей времени в обычной записи crontab пользователя?','3','4','5','6',2,'Минуты, часы, день месяца, месяц и день недели — пять временных полей.')
q('Почему желательно указать абсолютный путь к программе cron?','Окружение PATH в cron может отличаться','Cron запрещает PATH','Программа всегда становится root','Иначе время не считается',0,'Cron запускает задачи с ограниченным окружением, которое может не совпадать с интерактивным shell.')

lesson('Python для системного администратора','Для сложных форматов и надёжного парсинга Python удобнее комбинации grep/sed.',
'Стандартные модули `pathlib`, `subprocess`, `json`, `csv`, `argparse`, `logging` решают множество задач без дополнительных зависимостей. Используйте `subprocess.run([...], check=True)` с **списком аргументов**, а не `shell=True` для пользовательских данных. `Path.read_text()` и `write_text()` учитывают кодировку; `json.load()` делает структурный разбор. Обрабатывайте `FileNotFoundError` и используйте атомарную запись временного файла при замене критичной конфигурации.',
'python3 - <<\x27PY\x27\nimport json\nfrom pathlib import Path\nreport={"status":"ok","hosts":3}\nPath("/workspace/report.json").write_text(json.dumps(report),encoding="utf-8")\nprint(json.loads(Path("/workspace/report.json").read_text()))\nPY',
'Никогда не передавайте недоверенную строку напрямую в shell=True. Для запуска внешних программ используйте список аргументов.')
task('JSON-отчёт','Создайте `/workspace/report.json`, валидный JSON с ключами `status` = `ok` и `hosts` = число 3.',check('JSON распарсился и содержит верные значения',"python3 -c 'import json; d=json.load(open(\"/workspace/report.json\")); assert d[\"status\"]==\"ok\" and d[\"hosts\"]==3'"))
q('Почему subprocess.run(["ls", path]) безопаснее shell=True?','Не передаёт строку через shell-интерпретатор','Всегда быстрее в 100 раз','Не требует прав доступа','Автоматически даёт sudo',0,'Список аргументов позволяет избежать shell-инъекций через метасимволы команды.')
q('Какой модуль стандартной библиотеки читает JSON?','json','pickle только','random','syslog',0,'Модуль json реализует парсинг и генерацию JSON.')

module('Диагностика и защита','Логи, сети, hardening, резервное копирование и инциденты.')
lesson('Системные логи и journalctl','Ошибка сервиса без чтения логов — почти всегда догадка.',
'На systemd-системах `journalctl -u service --since today`, `journalctl -p err -b` позволяют фильтровать журнал. Текстовые логи часто находятся в `/var/log`, logrotate ограничивает размер и срок хранения. Диагностика: найдите время ошибки, код возврата, correlated events и первопричину, затем воспроизведите в тестовой среде. В контейнерной лаборатории journal может отсутствовать, поэтому используйте подготовленные журналы.',
'ls -l /var/log | head\n# В VM: journalctl -u ssh --since "1 hour ago"\n# В VM: journalctl -p warning -b --no-pager\n# В VM: systemctl status ssh',
'Не удаляйте произвольно `/var/log/journal`; настройте сроки хранения и ротацию. Для enterprise-систем используйте центральный сбор логов.',vm=True)
task('Найти первопричину в логе','Из `/workspace/incident.log` определите причину сбоя, запишите **ровно** `disk_full` в `/workspace/rootcause.txt`.',check('Причина диагностирована',"test \"$(cat /workspace/rootcause.txt)\" = disk_full"),setup="printf '10:01 INFO starting\\n10:02 ERROR write failed: no space left on device\\n10:03 WARN service degraded\\n10:04 ERROR healthcheck failed\\n' > /workspace/incident.log")
q('Как ограничить journalctl конкретным unit?','-u имя.service','-z имя.service','-d имя.service','-f имя.service для выбора unit',0,'Опция -u выбирает записи указанного systemd unit.')
q('Для чего logrotate?','Ограничить размер и историю логов','Заменить journalctl','Создать пользователей','Удалить GRUB',0,'logrotate выполняет ротацию, сжатие и очистку файловых журналов по правилам.')

lesson('Базовый hardening Linux','Безопасность — набор мер: обновления, минимум прав, сеть, контроль доступа и аудит.',
'Базовые практики: обновлять ОС из доверенных репозиториев, отделять администраторов и сервисные учётки, запрещать ненужные входы, использовать SSH-ключи, минимизировать сетевые порты и соблюдать разделение окружений. `ss -lntup` показывает потенциальные слушатели, `getent passwd` локальные учётки, `find /... -perm -4000` помогает аудитить SUID. Права секретов часто `600`; служба должна работать под отдельным пользователем, если ей не нужен root. Сетевые политики на production задаются firewall/NGFW и проверяются из независимых сегментов.',
'find /workspace -type f -perm /002 -print\nstat -c "%a %U:%G %n" /workspace\ngetent passwd | cut -d: -f1 | head\nss -lntup',
'Никогда не применяйте массово chmod по `/etc`, `/usr` или `/var` без знания сервисов и системы управления пакетами.')
task('Аудит небезопасных файлов','Найдите в `/workspace/audit` файлы, у которых разрешена запись всем (`other-write`), и сохраните их имена в `/workspace/world-writable.txt` отсортированными.',check('Обнаружены только проблемные файлы',"test \"$(cat /workspace/world-writable.txt)\" = \"$(printf 'bad1.txt\\nbad2.txt')\""),setup="mkdir -p /workspace/audit; touch /workspace/audit/bad1.txt /workspace/audit/bad2.txt /workspace/audit/good.txt; chmod 666 /workspace/audit/bad1.txt; chmod 622 /workspace/audit/bad2.txt; chmod 640 /workspace/audit/good.txt",hint='find ... -perm /002 -printf "%f\\n" | sort')
q('Какой принцип говорит выдавать только нужные права?','Least privilege','Always root','Full access by default','Network trust',0,'Least privilege снижает последствия компрометации пользователя или сервиса.')
q('Чем опасны world-writable конфигурации?','Любой локальный пользователь может их менять','Они сжимают файлы','Они выключают IPv6','Они мешают grep',0,'Право записи для others позволяет посторонним локальным аккаунтам изменять данные.')

lesson('Резервирование, RPO/RTO и восстановление','Сохранить архив не значит выполнить полноценное резервное копирование.',
'**RPO** — сколько данных допустимо потерять по времени, **RTO** — сколько может длиться восстановление. Следите за согласованностью приложений: копирование активной БД на уровне файлов без режима backup может быть неконсистентным. Правило 3-2-1 предусматривает дополнительные копии на разных носителях, одна из них вне основной площадки. Шифрование, контрольные суммы, пробные восстановления и неизменяемое/оффлайновое хранение повышают надёжность. Для Linux-проекта часто используют rsync, tar, restic или системный enterprise backup; конкретный инструмент зависит от рисков.',
'rsync -av --dry-run /workspace/source/ /workspace/dest/\ntar -tzf /workspace/backup.tar.gz\nsha256sum /workspace/backup.tar.gz',
'Сначала делайте dry-run rsync. Особенно осторожно с `--delete`: он удаляет элементы цели, отсутствующие в источнике.')
task('Проверка резервной копии','Скопируйте дерево `/workspace/source` в `/workspace/backup` сохранив структуру; исправьте это без удаления источника.',check('Содержимое config совпадает',"cmp -s /workspace/source/config/app.conf /workspace/backup/config/app.conf"),check('Содержимое data совпадает',"cmp -s /workspace/source/data/values.txt /workspace/backup/data/values.txt"),setup="mkdir -p /workspace/source/config /workspace/source/data; printf 'debug=false\\n' >/workspace/source/config/app.conf; printf 'a,b,c\\n' >/workspace/source/data/values.txt",hint='cp -a /workspace/source/. /workspace/backup/ или rsync -a.')
q('Что означает RPO?','Допустимый объём потери данных во времени','Максимальное время простоя','Размер swap','Количество CPU',0,'Recovery Point Objective описывает допустимую точку восстановления относительно потери данных.')
q('Почему важен тест восстановления?','Наличие архива само по себе не гарантирует восстановимость','Для ускорения cron','Чтобы увеличить chmod','Чтобы выключить SSH',0,'Проверка восстановления выявляет ошибки резервирования и неправильные предположения.')

module('Администрирование и DevOps','Git, Ansible, контейнеры и диагностика автоматизации.')
lesson('Git: коммиты, ветки и diff','Инфраструктурные сценарии и конфигурации стоит хранить под контролем версий.',
'Git хранит снимки файлов в коммитах. `git init` создаёт репозиторий, `git status` показывает изменения, `git add` индексирует, `git commit` сохраняет, `git diff` сравнивает рабочие файлы, `git log --oneline` выводит историю. Ветки позволяют отделить изменения, но секреты и приватные ключи не должны попадать в историю: даже удаление из последнего коммита не гарантирует удаление из старых. `.gitignore` помогает исключать локальные файлы, однако уже отслеживаемые файлы он не удалит из индекса.',
'cd /workspace\nmkdir -p infra && cd infra\ngit init\ngit config user.name "Student"\ngit config user.email "student@lab.invalid"\necho "# Infrastructure" > README.md\ngit add README.md && git commit -m initial\ngit status -sb',
'Настройка user.name/email в примере локальна для учебного репозитория. Не переносите личные токены в `.git/config` или коммиты.')
task('Создать первый коммит','В `/workspace/git-project` инициализируйте git-репозиторий и закоммитьте `README.md` с текстом `Linux Academy`.',check('Git репозиторий существует',"git -C /workspace/git-project rev-parse --is-inside-work-tree | grep -Fxq true"),check('Есть хотя бы один коммит',"git -C /workspace/git-project rev-parse HEAD >/dev/null"),check('README в HEAD',"test \"$(git -C /workspace/git-project show HEAD:README.md)\" = 'Linux Academy'"),setup="mkdir -p /workspace/git-project")
q('Что делает git add?','Добавляет изменения в индекс для коммита','Отправляет на GitHub','Удаляет репозиторий','Запускает CI',0,'git add формирует staged-содержимое для следующего коммита.')
q('Зачем .gitignore?','Указать файлы, которые Git не должен начинать отслеживать','Скрыть ошибки компиляции','Включить HTTPS','Автоматически стереть секреты из истории',0,'.gitignore влияет на поиск неотслеживаемых файлов, но не чистит историю.')

lesson('Ansible: inventory и доступ по SSH','Ansible управляет Linux-машинами через SSH без постоянного агента на управляемом сервере.',
'Контроллер читает inventory и playbook и запускает модули на целевых хостах. В inventory группируют машины, задают `ansible_user`, `ansible_port`, `ansible_python_interpreter`. Обычно используется SSH-ключ и отдельный аккаунт автоматизации с контролируемым `become`. Для проверки связи подходят `ansible -m ping`, а `--check --diff` моделирует многие изменения, но не все модули полностью поддерживают check mode. Внутри браузерных лабораторий SSH-сеть выключена, поэтому создавайте inventory как документ; для реальных playbook используйте отдельный учебный контроллер/VM.',
'cat > /workspace/hosts.ini <<\x27EOF2\x27\n[ubuntu]\nlab1 ansible_host=192.0.2.11 ansible_user=ansible\n[debian]\nlab2 ansible_host=192.0.2.12 ansible_user=ansible\nEOF2\n# На контроллере: ansible -i hosts.ini all -m ping',
'При проблемах разделяйте DNS/SSH, host key verification, ключ/логин, become, Python-интерпретатор и синтаксис inventory.',vm=True)
task('Создать inventory','Создайте `/workspace/ansible/hosts.ini` с группой `[ubuntu]` и строкой `testhost ansible_host=192.0.2.50 ansible_user=ansible`.',check('Группа задана',"grep -Fxq '[ubuntu]' /workspace/ansible/hosts.ini"),check('Хост описан',"grep -Fxq 'testhost ansible_host=192.0.2.50 ansible_user=ansible' /workspace/ansible/hosts.ini"))
q('Как Ansible обычно подключается к Linux-хостам?','По SSH','По RDP','Через SMTP','Через GUI по VNC',0,'Управляющая нода Ansible обычно выполняет задания на Linux через SSH.')
q('Что делает --check в ansible-playbook?','Режим моделирования изменений для поддерживаемых модулей','Всегда применяет изменения','Удаляет inventory','Отключает SSH',0,'Check mode пытается предсказать изменения, не применяя их, если модуль поддерживает этот режим.')

lesson('Ansible: playbook, идемпотентность и handlers','Ценность Ansible — повторяемая желаемая конфигурация, а не удалённое исполнение команд.',
'Playbook — YAML со списком plays, каждый описывает `hosts`, `become`, `tasks`. Модули `ansible.builtin.apt`, `user`, `file`, `copy`, `template`, `service` меняют состояния. Идемпотентность — повторный запуск без новых изменений, если состояние уже достигнуто. `notify` запускает handler при фактическом изменении задачи. Переменные лучше отделять от секретов, для последних использовать Ansible Vault. Нужны корректные отступы YAML и inventory, а в `hosts` должны быть реальные управляемые VM, не лабораторные контейнеры без сети.',
'cat > /workspace/base.yml <<\x27EOF2\x27\n- name: Prepare servers\n  hosts: ubuntu\n  become: true\n  tasks:\n    - name: Ensure curl present\n      ansible.builtin.apt:\n        name: curl\n        state: present\nEOF2\n# В VM-контроллере: ansible-playbook -i hosts.ini base.yml --check --diff',
'Не используйте shell/command вместо специализированных модулей там, где нужен идемпотентный результат.',vm=True)
task('Мини-playbook','Создайте `/workspace/ansible/base.yml` с `hosts: ubuntu`, `become: true` и задачей модуля `ansible.builtin.apt` для установки `curl`.',check('Указана целевая группа',"grep -Eq '^[[:space:]]*hosts:[[:space:]]*ubuntu[[:space:]]*$' /workspace/ansible/base.yml"),check('Включён become',"grep -Eq '^[[:space:]]*become:[[:space:]]*true[[:space:]]*$' /workspace/ansible/base.yml"),check('Есть модуль apt',"grep -Fq 'ansible.builtin.apt:' /workspace/ansible/base.yml"),check('Указан curl',"grep -Eq '^[[:space:]]*name:[[:space:]]*curl[[:space:]]*$' /workspace/ansible/base.yml"))
q('Что такое идемпотентность задачи?','Повторный запуск сохраняет достигнутое состояние без ненужных изменений','Команда запускается только ночью','Все задачи выполняются одновременно','Доступ есть только у root',0,'Идемпотентная задача стремится приводить систему к одному желаемому состоянию при повторных запусках.')
q('Когда запускается handler, вызванный notify?','Когда уведомляющая задача сообщает changed','При каждом запуске независимо от результата','Только после reboot','Только при ошибке SSH',0,'Handlers срабатывают по уведомлениям изменившихся задач и обычно выполняются в конце play.')

lesson('Контейнеры, namespaces и cgroups','Контейнерные практикумы безопаснее полных VM только при правильных ограничениях.',
'OCI-образ содержит слои файловой системы и метаданные запуска, а контейнер — экземпляр процесса с дополнительной изоляцией. Namespaces изолируют PID, mount, net, user и другие пространства; cgroups ограничивают память, CPU и число процессов. Rootless Podman не запускает контейнерный процесс как root на хосте, но это не абсолютная защита от уязвимостей ядра. Образ собирают Containerfile, контейнер запускают `podman run`, следят через `podman ps` и `podman logs`. Для задач с реальным ядром, systemd и блочными устройствами нужен VM-гипервизор, а не `--privileged`.',
'# На выделенном Linux-хосте:\npodman images\npodman ps -a\npodman inspect NAME\npodman logs NAME',
'Вложенный Podman намеренно не запущен внутри учебного контейнера. Команды из примера выполняются администратором на отдельном тестовом Podman-хосте.',vm=True)
q('Какую задачу решают cgroups?','Лимитирование и учёт ресурсов процессов','Редактирование файлов в git','Создание DNS-зон','Настройка BIOS',0,'Control groups позволяют ограничивать CPU, память, процессы и другие ресурсы групп задач.')
q('Что даёт rootless Podman?','Запуск контейнеров без root-прав в хостовой системе','Собственное ядро для каждого контейнера','Абсолютную невозможность побега из контейнера','Автоматическую защиту от любых ошибок',0,'Rootless снижает привилегии раннера и процессов относительно хоста, но не устраняет все угрозы.')

lesson('Мониторинг, метрики и эксплуатация','Нужен не только запуск службы, но и понимание её работоспособности.',
'Для инфраструктуры важны метрики доступности, задержки, ошибок, ресурсов CPU/RAM/диска, пропускной способности и состояния резервирования. Zabbix/Prometheus/Grafana и syslog-системы помогают собирать телеметрию. Оповещения должны сопровождаться runbook: симптомы, диагностика, безопасные действия, проверка результата и обратный откат. Не все WARNING требуют аварийной реакции. Устанавливайте SLO для сервиса и отделяйте простое наличие PID от прикладного healthcheck.',
'uptime\nfree -h\ndf -h /workspace\nps -eo pid,%cpu,%mem,cmd --sort=-%cpu | head',
'Здоровый процесс не гарантирует доступности приложения. Для мониторинга HTTP-проверка и пользовательская транзакция информативнее одного PID.')
task('Runbook сервиса','Создайте `/workspace/runbook.txt` минимум с тремя строками, начинающимися `SYMPTOM:`, `CHECK:`, `RECOVERY:`.',check('Есть описание симптома',"grep -q '^SYMPTOM:.' /workspace/runbook.txt"),check('Есть диагностика',"grep -q '^CHECK:.' /workspace/runbook.txt"),check('Есть восстановление',"grep -q '^RECOVERY:.' /workspace/runbook.txt"))
q('Что лучше показывает фактическую работоспособность веб-сервиса?','HTTP healthcheck приложения','Наличие процесса sleep','Размер исходников','Имя пользователя',0,'Прикладная проверка может обнаружить неисправность даже при существующем PID.')
q('Что должен содержать runbook?','Диагностику и безопасные шаги восстановления','Только URL сайта','Только скриншоты','Только имена сотрудников',0,'Пошаговая процедура помогает воспроизводимо реагировать на инцидент и оценивать результат.')

module('Итоговые практикумы','Сборные сценарии: диагностировать, исправить, проверить и документировать.')
lesson('Инцидент: неверные права доступа','Объедините знания о каталогах, владельцах, режимах и проверках.',
'В реальной эксплуатации ошибка доступа может возникнуть из-за прав файла, прав каждого каталога по пути, группы процесса, ACL, SELinux/AppArmor или монтирования read-only. Начинайте с `id`, `namei -l path`, `stat`, `getfacl`, затем смотрите журнал. Не назначайте режим 777 для обхода причины. В этом практикуме требуется точечно исправить только указанные артефакты, не затрагивая другую структуру. После исправления выполните машинную проверку и повторите оценку урока.',
'ls -ld /workspace/scenario\nstat -c "%a %U:%G %n" /workspace/scenario/*\nchmod 640 /workspace/scenario/secret.ini\nchmod 750 /workspace/scenario/bin',
'Не применяйте рекурсивный chmod ко всему каталогу: файлы данных не должны становиться исполняемыми.')
task('Восстановление прав приложения','Исправьте `/workspace/scenario/secret.ini` до 640, каталог `/workspace/scenario/bin` до 750 и скрипт `/workspace/scenario/bin/start.sh` до 750.',check('Конфигурация защищена',"test \"$(stat -c %a /workspace/scenario/secret.ini)\" = 640"),check('Каталог ограничен',"test \"$(stat -c %a /workspace/scenario/bin)\" = 750"),check('Скрипт может исполняться',"test \"$(stat -c %a /workspace/scenario/bin/start.sh)\" = 750"),setup="mkdir -p /workspace/scenario/bin; echo 'token=demo' > /workspace/scenario/secret.ini; printf '#!/bin/bash\\necho app\\n' > /workspace/scenario/bin/start.sh; chmod 777 /workspace/scenario/secret.ini /workspace/scenario/bin /workspace/scenario/bin/start.sh")
q('Что проверить при Permission denied на файл?','Права файла и права прохода по каталогам','Только hostname','Только температуру','Только apt update',0,'Доступ к файлу требует права прохода по каждому каталогу пути.')
q('Почему не нужно chmod -R 777?','Раскрывает данные и права изменения лишним пользователям','Включает резервное копирование','Проверяет SELinux','Отключает сеть',0,'Массовая выдача rwx может создать угрозы целостности и конфиденциальности.')

lesson('Инцидент: отчёт о недоступности API','Тренируйтесь выводить факты из логов и проверять результат по нескольким признакам.',
'Для веб-сервиса проверяйте журнал, код HTTP-ответа, время инцидента, DNS и маршрут до endpoint, состояние backend и доступность БД. Часто ответ 502/503 — следствие ошибки upstream, а не обязательно сетевой блокировки. В практикуме нужно собрать отчёт без доступа к корпоративной сети: вы анализируете подготовленные строки. Каждая проверка оценивает конкретный артефакт, а не наличие произвольного текста.',
'grep -nE "(502|503|ERROR)" /workspace/api.log\nawk "{print \\$2}" /workspace/api.log | sort | uniq -c\n# Сформируйте отчет с кодами и типом сбоя',
'Не заменяйте анализ симптома перезапуском всего сервера. Сначала найдите источник ошибки.')
task('Сводка инцидента','В `/workspace/api.log` код 503 встречается трижды. Создайте `/workspace/incident-summary.txt` с двумя строками `HTTP_503=3` и `ROOT_CAUSE=db_timeout`.',check('Количество 503 верно',"grep -Fxq 'HTTP_503=3' /workspace/incident-summary.txt"),check('Корневая причина верна',"grep -Fxq 'ROOT_CAUSE=db_timeout' /workspace/incident-summary.txt"),setup="printf '10:00 200 GET /health\\n10:01 503 GET /api\\n10:01 ERROR db_timeout\\n10:02 503 GET /api\\n10:03 200 GET /health\\n10:04 503 GET /api\\n' > /workspace/api.log")
q('Что означает HTTP 503?','Service Unavailable','Unauthorized','Not Found','Moved Permanently',0,'HTTP 503 указывает, что сервер в данный момент не может обслужить запрос.')
q('Почему 503 не доказывает проблему DNS?','HTTP-код уже получен от сервера или посредника','503 выдаёт локальный ls','DNS работает только с UDP 53','503 означает всегда SSL-ошибку',0,'Ответ 503 означает, что HTTP-соединение дошло до компонента, сформировавшего ответ.')

lesson('Финальный проект: мини-администрирование Linux','Соберите знания о файлах, правах, bash и резервном копировании в одной практической задаче.',
'Проект состоит из нескольких независимых критериев: создайте структуру сервиса, скрипт проверки конфигурации, права доступа и backup-архив. Соблюдайте минимальные привилегии, кавычки вокруг путей, код возврата и проверку содержимого архива. Лаборатория проверит артефакты автоматически. Дополнительно составьте небольшой собственный runbook и повторите весь сценарий после сброса окружения — так проверяется воспроизводимость, а не случайное совпадение.',
'mkdir -p /workspace/final/{etc,bin,backup}\nprintf "enabled=true\\n" > /workspace/final/etc/service.conf\nchmod 640 /workspace/final/etc/service.conf\n# Далее создайте скрипт, архив и запустите проверки',
'В конце сбросьте лабораторию и выполните сценарий заново на время: администрирование ценно воспроизводимым результатом.')
task('Собрать структуру сервиса','Создайте конфигурацию `/workspace/final/etc/service.conf` со строкой `enabled=true`, права файла строго 640.',check('Файл содержит настройку',"grep -Fxq 'enabled=true' /workspace/final/etc/service.conf"),check('Права 640',"test \"$(stat -c %a /workspace/final/etc/service.conf)\" = 640"))
task('Написать проверку настроек','Создайте исполняемый `/workspace/final/bin/check.sh`: если в `/workspace/final/etc/service.conf` есть `enabled=true`, выведите `READY`; иначе `ERROR`.',check('Выдаёт READY при корректном конфиге',"test \"$(/workspace/final/bin/check.sh)\" = READY"),check('Скрипт исполняемый',"test -x /workspace/final/bin/check.sh"))
task('Создать архив проекта','Создайте `/workspace/final-backup.tar.gz`, содержащий `final/etc/service.conf`.',check('Архив существует',"test -s /workspace/final-backup.tar.gz"),check('Конфиг присутствует',"tar -tzf /workspace/final-backup.tar.gz | grep -Fxq 'final/etc/service.conf'"))
q('Что подтверждает успешное резервное копирование?','Возможность проверить и восстановить данные','Только имя файла backup.tar.gz','Размер больше нуля без проверки','Наличие команды tar в PATH',0,'Нужны проверки структуры, целостности и возможности восстановления.')
q('Какой режим прав подходит конфигу без прав для остальных?','777','666','640','755',2,'640 предоставляет чтение/запись владельцу, чтение группе и не даёт доступа остальным.')

for m in modules:
    for l in m['lessons']:
        assert l['quiz'],l['id']
        for t in l['tasks']:
            assert t['checks'],t['id']

out=Path(__file__).with_name('curriculum.json')
out.write_text(json.dumps(modules,ensure_ascii=False,indent=2),encoding='utf-8')
print('Generated',out,'modules',len(modules),'lessons',sum(len(x['lessons']) for x in modules),'tasks',sum(len(l['tasks']) for m in modules for l in m['lessons']),'questions',sum(len(l['quiz']) for m in modules for l in m['lessons']))
